with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , SCHEME_CODE as SCHEME_CODE
        , SCHEME_VERSION as SCHEME_VERSION
        , 'BJAZ_CTNGY_NR_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_nr_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then SCHEME_CODE end) as SCHEME_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then SCHEME_VERSION end) as SCHEME_VERSION,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when SCHEME_CODE is not null or SCHEME_VERSION is not null
                     then md5(upper(coalesce(cast(SCHEME_CODE as varchar), '') || '|' || coalesce(cast(SCHEME_VERSION as varchar), '')))
                end as SAT_POLICY_CONTINGENCY_SCHEME_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_CONTINGENCY_SCHEME_HASHDIFF is not null
